"""
    Finds all unique integers in the list that add up to the target number.

    :param nums: List of integers.
    :param target: Target integer to find in the list.
    :return: A set of unique integers that add up to the target.
    """
    seen = {}
    for num in nums:
        complement = target - num
        if complement in seen and seen[complement] != num:
            return {num}
        elif complement not in seen or seen[complement] < num:
            seen[num] = num
    return set()

